// pages/PropertyForm.js
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getProperty, createProperty, updateProperty, getOffices } from '../apiService';

const PropertyForm = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [offices, setOffices] = useState([]);
  const [formData, setFormData] = useState({
    office_id: '',
    property_name: '',
    address: '',
    remodel_status: '',
    furnish_status: '',
    num_bedrooms: '',
    num_bathrooms: '',
    laundry_location: '',
    lease_duration: '',
    price_per_person: '',
    distance_to_walc: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const isEditMode = !!id;

  useEffect(() => {
    const loadOffices = async () => {
      try {
        const data = await getOffices();
        setOffices(data);
      } catch (err) {
        console.error('Failed to load offices', err);
      }
    };

    const loadProperty = async () => {
      if (isEditMode) {
        setLoading(true);
        try {
          const property = await getProperty(id);
          setFormData({
            office_id: property.office_id || '',
            property_name: property.property_name || '',
            address: property.address || '',
            remodel_status: property.remodel_status || '',
            furnish_status: property.furnish_status || '',
            num_bedrooms: property.num_bedrooms || '',
            num_bathrooms: property.num_bathrooms || '',
            laundry_location: property.laundry_location || '',
            lease_duration: property.lease_duration || '',
            price_per_person: property.price_per_person || '',
            distance_to_walc: property.distance_to_walc || ''
          });
        } catch (err) {
          setError('Failed to load property data. Please try again.');
          console.error(err);
        } finally {
          setLoading(false);
        }
      }
    };

    loadOffices();
    loadProperty();
  }, [id, isEditMode]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      // Convert numeric fields
      const propertyData = {
        ...formData,
        office_id: formData.office_id === '' ? null : Number(formData.office_id),
        num_bedrooms: Number(formData.num_bedrooms),
        num_bathrooms: Number(formData.num_bathrooms),
        lease_duration: Number(formData.lease_duration),
        price_per_person: Number(formData.price_per_person),
        distance_to_walc: Number(formData.distance_to_walc)
      };

      if (isEditMode) {
        await updateProperty(id, propertyData);
      } else {
        await createProperty(propertyData);
      }
      navigate('/properties');
    } catch (err) {
      setError(`Failed to ${isEditMode ? 'update' : 'create'} property. Please check your inputs.`);
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  if (loading && isEditMode) {
    return <div className="text-center py-10">Loading property data...</div>;
  }

  return (
    <div className="max-w-2xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">
        {isEditMode ? 'Edit Property' : 'Add New Property'}
      </h1>
      
      {error && (
        <div className="bg-red-100 text-red-700 p-4 rounded mb-4">
          {error}
        </div>
      )}
      
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Leasing Office</label>
          <select
            name="office_id"
            value={formData.office_id}
            onChange={handleChange}
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Leasing Office</option>
            {offices.map(office => (
              <option key={office.office_id} value={office.office_id}>
                {office.name}
              </option>
            ))}
          </select>
        </div>
        
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Property Name</label>
          <input
            type="text"
            name="property_name"
            value={formData.property_name}
            onChange={handleChange}
            required
            className="w-full p-2 border border-gray-300 rounded"
          />
        </div>
        
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Address</label>
          <input
            type="text"
            name="address"
            value={formData.address}
            onChange={handleChange}
            required
            className="w-full p-2 border border-gray-300 rounded"
          />
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Remodel Status</label>
            <select
              name="remodel_status"
              value={formData.remodel_status}
              onChange={handleChange}
              required
              className="w-full p-2 border border-gray-300 rounded"
            >
              <option value="">Select Status</option>
              <option value="Recently Remodeled">Recently Remodeled</option>
              <option value="Needs Remodeling">Needs Remodeling</option>
              <option value="Currently Remodeling">Currently Remodeling</option>
            </select>
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Furnish Status</label>
            <select
              name="furnish_status"
              value={formData.furnish_status}
              onChange={handleChange}
              required
              className="w-full p-2 border border-gray-300 rounded"
            >
              <option value="">Select Status</option>
              <option value="Furnished">Furnished</option>
              <option value="Unfurnished">Unfurnished</option>
              <option value="Partially Furnished">Partially Furnished</option>
            </select>
          </div>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Bedrooms</label>
            <input
              type="number"
              name="num_bedrooms"
              value={formData.num_bedrooms}
              onChange={handleChange}
              required
              min="0"
              className="w-full p-2 border border-gray-300 rounded"
            />
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Bathrooms</label>
            <input
              type="number"
              name="num_bathrooms"
              value={formData.num_bathrooms}
              onChange={handleChange}
              required
              min="0"
              step="0.5"
              className="w-full p-2 border border-gray-300 rounded"
            />
          </div>
        </div>
        
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Laundry Location</label>
          <select
            name="laundry_location"
            value={formData.laundry_location}
            onChange={handleChange}
            required
            className="w-full p-2 border border-gray-300 rounded"
          >
            <option value="">Select Location</option>
            <option value="In Unit">In Unit</option>
            <option value="In Building">In Building</option>
            <option value="None">None</option>
          </select>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Lease Duration (months)</label>
            <input
              type="number"
              name="lease_duration"
              value={formData.lease_duration}
              onChange={handleChange}
              required
              min="1"
              className="w-full p-2 border border-gray-300 rounded"
            />
          </div>
          
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Price Per Person ($)</label>
            <input
              type="number"
              name="price_per_person"
              value={formData.price_per_person}
              onChange={handleChange}
              required
              min="0"
              step="0.01"
              className="w-full p-2 border border-gray-300 rounded"
            />
          </div>
        </div>
        
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Distance to Campus (miles)</label>
          <input
            type="number"
            name="distance_to_walc"
            value={formData.distance_to_walc}
            onChange={handleChange}
            required
            min="0"
            step="0.1"
            className="w-full p-2 border border-gray-300 rounded"
          />
        </div>
        
        <div className="flex justify-end space-x-2 pt-4">
          <button
            type="button"
            onClick={() => navigate('/properties')}
            className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={loading}
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:bg-blue-300"
          >
            {loading ? 'Saving...' : (isEditMode ? 'Update Property' : 'Add Property')}
          </button>
        </div>
      </form>
    </div>
  );
};

export default PropertyForm;
